  "analyzer": {img:"🔬", ex5:[{t:1,en:"The lab uses a new blood analyzer.",kr:"연구실은 새로운 혈액 분석기를 사용한다."},{t:2,en:"This software is a powerful data analyzer.",kr:"이 소프트웨어는 강력한 데이터 분석기이다."},{t:3,en:"She is an expert systems analyzer.",kr:"그녀는 전문 시스템 분석가이다."},{t:4,en:"The analyzer shows that the air quality is good.",kr:"분석기는 공기 질이 좋다는 것을 보여준다."},{t:5,en:"We need a faster analyzer for this experiment.",kr:"우리는 이 실험을 위해 더 빠른 분석기가 필요하다."}]},
  "analyzes": {img:"🔍", ex5:[{t:1,en:"The scientist analyzes the soil samples every morning.",kr:"그 과학자는 매일 아침 토양 샘플을 분석한다."},{t:2,en:"She analyzes the market trends before making any investments.",kr:"그녀는 투자하기 전에 시장 동향을 분석한다."},{t:3,en:"My teacher analyzes my writing style to help me improve.",kr:"선생님은 내가 발전할 수 있도록 나의 글쓰기 스타일을 분석해 주신다."},{t:4,en:"The software analyzes data much faster than a human.",kr:"그 소프트웨어는 사람보다 훨씬 빠르게 데이터를 분석한다."},{t:5,en:"He analyzes every move his opponent makes in the game.",kr:"그는 경기에서 상대방의 모든 움직임을 분석한다."}]},
  "analyzing": {img:"🧪", ex5:[{t:1,en:"They keep analyzing.",kr:"그들은 계속 분석한다."},{t:2,en:"The act of analyzing takes time.",kr:"분석하는 일은 시간이 걸린다."},{t:3,en:"We are analyzing trends.",kr:"우리는 추세를 분석하고 있다."},{t:4,en:"The tool gave us analyzing power.",kr:"그 도구는 우리에게 분석력을 주었다."},{t:5,en:"We found them analyzing data.",kr:"우리는 그들이 데이터를 분석하는 것을 알았다."}]},
  "anand": {img:"👤", ex5:[{t:1,en:"Anand is a popular name in India.",kr:"아난드는 인도에서 인기 있는 이름이다."},{t:2,en:"I talked to Anand about our travel plans.",kr:"나는 아난드와 우리 여행 계획에 대해 이야기했다."},{t:3,en:"Anand helped me fix my broken laptop.",kr:"아난드가 고장 난 내 노트북을 고치는 것을 도와주었다."},{t:4,en:"Anand enjoys cooking delicious meals for his family.",kr:"아난드는 가족을 위해 맛있는 식사를 요리하는 것을 즐긴다."},{t:5,en:"Is Anand going to join the meeting today?",kr:"아난드가 오늘 회의에 참석할 예정인가요?"}]},
  "anaphylaxis": {img:"⚠️", ex5:[{t:1,en:"He carries an epinephrine pen in case of anaphylaxis.",kr:"그는 아나필락시스 발생에 대비해 에피네프린 펜을 휴대합니다."},{t:2,en:"Severe peanut allergies can lead to sudden anaphylaxis.",kr:"심각한 땅콩 알레르기는 갑작스러운 아나필락시스로 이어질 수 있습니다."},{t:3,en:"Medical staff treated her for anaphylaxis immediately.",kr:"의료진은 즉시 그녀를 아나필락시스 치료했습니다."},{t:4,en:"Anaphylaxis is a life-threatening allergic reaction.",kr:"아나필락시스는 생명을 위협하는 알레르기 반응입니다."},{t:5,en:"She went into anaphylaxis after being stung by a bee.",kr:"그녀는 벌에 쏘인 후 아나필락시스 상태에 빠졌습니다."}]},
  "anarchic": {img:"🌪️", ex5:[{t:1,en:"The classroom became anarchic after the teacher left.",kr:"선생님이 떠난 후 교실은 무질서한 상태가 되었다."},{t:2,en:"He lived an anarchic lifestyle without any rules.",kr:"그는 아무런 규칙도 없는 무질서한 삶을 살았다."},{t:3,en:"The protest turned into an anarchic scene.",kr:"시위는 무질서한 현장으로 변했다."},{t:4,en:"It is difficult to manage an anarchic group of people.",kr:"무질서한 사람들을 통제하는 것은 어렵다."},{t:5,en:"The movie portrayed an anarchic world of the future.",kr:"그 영화는 미래의 무질서한 세상을 묘사했다."}]},
  "anarchism": {img:"🏴", ex5:[{t:1,en:"He studied the history of anarchism in Europe.",kr:"그는 유럽의 무정부주의 역사를 공부했습니다."},{t:2,en:"Anarchism promotes the idea of a society without a state.",kr:"무정부주의는 국가 없는 사회라는 개념을 장려합니다."},{t:3,en:"The book explores the core values of anarchism.",kr:"그 책은 무정부주의의 핵심 가치를 탐구합니다."},{t:4,en:"Some people confuse anarchism with total chaos.",kr:"어떤 사람들은 무정부주의를 완전한 혼란과 혼동합니다."},{t:5,en:"His political views are deeply rooted in anarchism.",kr:"그의 정치적 견해는 무정부주의에 깊이 뿌리박고 있습니다."}]},
  "anarchist": {img:"🏴", ex5:[{t:1,en:"He considers himself a political anarchist.",kr:"그는 자신을 정치적 무정부주의자로 여긴다."},{t:2,en:"The anarchist wrote many essays on freedom.",kr:"그 무정부주의자는 자유에 관한 많은 에세이를 썼다."},{t:3,en:"Some people mistake an anarchist for a criminal.",kr:"어떤 사람들은 무정부주의자를 범죄자로 오해한다."},{t:4,en:"The anarchist movement grew in the city.",kr:"그 도시에서 무정부주의 운동이 성장했다."},{t:5,en:"She studied the history of the anarchist group.",kr:"그녀는 그 무정부주의 단체의 역사를 공부했다."}]},
  "anarchists": {img:"🚩", ex5:[{t:1,en:"The anarchists gathered to protest against the new law.",kr:"무정부주의자들은 새 법에 반대하기 위해 모였다."},{t:2,en:"Some anarchists believe in a society without a government.",kr:"일부 무정부주의자들은 정부가 없는 사회를 믿는다."},{t:3,en:"The book discusses the history of various anarchists.",kr:"그 책은 다양한 무정부주의자들의 역사를 다룬다."},{t:4,en:"The group of anarchists handed out flyers in the park.",kr:"그 무정부주의자 집단은 공원에서 전단지를 나누어 주었다."},{t:5,en:"There were many anarchists involved in the movement.",kr:"그 운동에 참여한 많은 무정부주의자가 있었다."}]},
  "anarchy": {img:"🌪️", ex5:[{t:1,en:"The situation turned into total anarchy.",kr:"상황은 완전한 무정부 상태로 변했습니다."},{t:2,en:"The school was in anarchy during the strike.",kr:"파업 기간 동안 학교는 혼란 그 자체였습니다."},{t:3,en:"They tried to prevent social anarchy.",kr:"그들은 사회적 혼란을 막으려 노력했습니다."},{t:4,en:"Without rules, the city would fall into anarchy.",kr:"규칙이 없다면 도시는 무정부 상태에 빠질 것입니다."},{t:5,en:"The country is suffering from political anarchy.",kr:"그 나라는 정치적 혼란으로 고통받고 있습니다."}]},
  "anastasia": {img:"👸", ex5:[{t:1,en:"Anastasia is coming to the party tonight.",kr:"아나스타샤가 오늘 밤 파티에 올 거야."},{t:2,en:"I met a girl named Anastasia at the library.",kr:"나는 도서관에서 아나스타샤라는 이름의 소녀를 만났다."},{t:3,en:"Anastasia wants to be a professional dancer.",kr:"아나스타샤는 전문 댄서가 되고 싶어 한다."},{t:4,en:"Did you see Anastasia during the lunch break?",kr:"점심시간에 아나스타샤를 봤니?"},{t:5,en:"Anastasia is my best friend in this city.",kr:"아나스타샤는 이 도시에서 나의 가장 친한 친구야."}]},
