  "ancestry": {img:"🌳", ex5:[{t:1,en:"Her ancestry runs deep.",kr:"그녀의 혈통은 뿌리가 깊다."},{t:2,en:"The ancestry is mixed.",kr:"그 혈통은 혼합되어 있다."},{t:3,en:"We traced our ancestry.",kr:"우리는 우리의 혈통을 추적했다."},{t:4,en:"The test gave us ancestry results.",kr:"그 검사는 우리에게 혈통 결과를 주었다."},{t:5,en:"We found our ancestry diverse.",kr:"우리는 우리 혈통이 다채로움을 알았다."}]},
  "anchor": {img:"⚓", ex5:[{t:1,en:"The anchor dropped.",kr:"닻이 내려졌다."},{t:2,en:"The anchor is heavy.",kr:"그 닻은 무겁다."},{t:3,en:"We dropped the anchor.",kr:"우리는 닻을 내렸다."},{t:4,en:"The crew gave the boat an anchor.",kr:"선원들은 그 배에 닻을 내려 주었다."},{t:5,en:"We found the anchor stuck.",kr:"우리는 그 닻이 박힌 것을 알았다."}]},
  "anchorage": {img:"⚓", ex5:[{t:1,en:"The anchorage is calm.",kr:"그 정박지는 잔잔하다."},{t:2,en:"The anchorage was full.",kr:"그 정박지는 가득 찼다."},{t:3,en:"We reached the anchorage.",kr:"우리는 정박지에 도착했다."},{t:4,en:"The harbor gave us an anchorage.",kr:"그 항구는 우리에게 정박지를 내주었다."},{t:5,en:"We found the anchorage sheltered.",kr:"우리는 그 정박지가 안전하다고 느꼈다."}]},
  "anchored": {img:"🛥️", ex5:[{t:1,en:"The ship anchored.",kr:"그 배는 정박했다."},{t:2,en:"The boat is anchored.",kr:"그 배는 닻을 내리고 있다."},{t:3,en:"They anchored the raft.",kr:"그들은 뗏목을 고정했다."},{t:4,en:"The bay gave us a place anchored safe.",kr:"그 만은 우리에게 안전히 정박할 곳을 주었다."},{t:5,en:"We found the vessel anchored.",kr:"우리는 그 배가 정박한 것을 알았다."}]},
  "anchoring": {img:"⚓", ex5:[{t:1,en:"The boat is anchoring in the calm bay.",kr:"배가 잔잔한 만에 닻을 내리고 있다."},{t:2,en:"Anchoring your beliefs in facts is important.",kr:"사실에 당신의 신념을 근거 짓는 것은 중요하다."},{t:3,en:"The news anchor is anchoring the evening broadcast.",kr:"그 뉴스 앵커가 저녁 방송을 진행하고 있다."},{t:4,en:"The process of anchoring the balloon was difficult.",kr:"풍선을 고정하는 과정은 어려웠다."},{t:5,en:"The strong anchoring secured the structure against the wind.",kr:"튼튼한 고정이 바람에 구조물을 안전하게 지켰다."}]},
  "anchorman": {img:"🎙️", ex5:[{t:1,en:"The famous anchorman retired after thirty years of news reporting.",kr:"그 유명한 앵커는 30년간의 뉴스 보도를 마치고 은퇴했다."},{t:2,en:"He dreams of becoming a professional anchorman one day.",kr:"그는 언젠가 전문 앵커가 되는 것을 꿈꾼다."},{t:3,en:"The anchorman delivered the breaking news with a calm voice.",kr:"그 앵커는 차분한 목소리로 긴급 뉴스를 전달했다."},{t:4,en:"Many people trust the information shared by the lead anchorman.",kr:"많은 사람들이 메인 앵커가 전하는 정보를 신뢰한다."},{t:5,en:"The anchorman prepared for the evening broadcast all afternoon.",kr:"그 앵커는 오후 내내 저녁 방송을 준비했다."}]},
  "anchors": {img:"⚓", ex5:[{t:1,en:"The sailors lifted the heavy anchors before leaving the port.",kr:"선원들은 항구를 떠나기 전에 무거운 닻을 올렸습니다."},{t:2,en:"The ship dropped its anchors in the calm bay.",kr:"배는 잔잔한 만에 닻을 내렸습니다."},{t:3,en:"The museum displays old anchors found under the sea.",kr:"박물관은 바닷속에서 발견된 오래된 닻들을 전시합니다."},{t:4,en:"The heavy iron anchors keep the boats from drifting.",kr:"무거운 철제 닻들은 배가 떠내려가지 않게 잡아줍니다."},{t:5,en:"They checked the anchors to ensure the ship was secure.",kr:"그들은 배가 안전한지 확인하기 위해 닻을 점검했습니다."}]},
  "anchovies": {img:"🐟", ex5:[{t:1,en:"I love adding salty anchovies to my pasta sauce.",kr:"나는 파스타 소스에 짭짤한 멸치를 넣는 것을 좋아한다."},{t:2,en:"Some people hate having anchovies on their pizza.",kr:"어떤 사람들은 피자 위에 멸치가 올라가는 것을 싫어한다."},{t:3,en:"The fisherman caught a large net full of anchovies.",kr:"어부는 멸치로 가득 찬 큰 그물을 낚았다."},{t:4,en:"Anchovies are a great source of calcium.",kr:"멸치는 훌륭한 칼슘 공급원이다."},{t:5,en:"Would you like me to remove the anchovies from the salad?",kr:"샐러드에서 멸치를 빼드릴까요?"}]},
  "anchovy": {img:"🐟", ex5:[{t:1,en:"She added an anchovy to the sauce for depth.",kr:"그녀는 깊은 맛을 위해 소스에 멸치를 넣었다."},{t:2,en:"The pizza was topped with salty anchovy.",kr:"그 피자에는 짭짤한 멸치가 얹혀 있었다."},{t:3,en:"An anchovy adds a savory, umami taste.",kr:"멸치는 감칠맛 나는 풍미를 더한다."},{t:4,en:"He dislikes the strong taste of anchovy.",kr:"그는 멸치의 강한 맛을 싫어한다."},{t:5,en:"A tin of anchovy sat in the pantry.",kr:"멸치 통조림 하나가 식료품 저장실에 있었다."}]},
