  "andalusia": {img:"💃", ex5:[{t:1,en:"We are planning a trip to Andalusia next summer.",kr:"우리는 내년 여름에 안달루시아로 여행을 계획 중이에요."},{t:2,en:"Andalusia is famous for its beautiful flamenco dancing.",kr:"안달루시아는 아름다운 플라멩코 춤으로 유명해요."},{t:3,en:"The climate in Andalusia is very sunny and warm.",kr:"안달루시아의 기후는 매우 화창하고 따뜻해요."},{t:4,en:"Many tourists visit the historic cities of Andalusia.",kr:"많은 관광객들이 안달루시아의 역사적인 도시들을 방문해요."},{t:5,en:"My favorite region in Spain is Andalusia.",kr:"내가 스페인에서 가장 좋아하는 지역은 안달루시아예요."}]},
  "andaman": {img:"🏝️", ex5:[{t:1,en:"We went on a trip to the Andaman Islands.",kr:"우리는 안다만 제도로 여행을 갔다."},{t:2,en:"The Andaman Sea is famous for its clear water.",kr:"안다만 해는 맑은 물로 유명하다."},{t:3,en:"Many tourists visit the Andaman region for diving.",kr:"많은 관광객이 다이빙을 하러 안다만 지역을 찾는다."},{t:4,en:"The Andaman Islands are located in the Indian Ocean.",kr:"안다만 제도는 인도양에 위치해 있다."},{t:5,en:"We enjoyed the white beaches of Andaman.",kr:"우리는 안다만의 하얀 해변을 즐겼다."}]},
  "anders": {img:"🧔", ex5:[{t:1,en:"Anders is a very talented musician.",kr:"안데르스는 매우 재능 있는 음악가이다."},{t:2,en:"I sent an email to Anders regarding the plan.",kr:"나는 계획에 관해 안데르스에게 이메일을 보냈다."},{t:3,en:"Anders will lead the meeting this afternoon.",kr:"안데르스가 오늘 오후 회의를 이끌 것이다."},{t:4,en:"Have you heard from Anders lately?",kr:"최근에 안데르스에게 연락받은 적 있나요?"},{t:5,en:"Anders decided to join our hiking club.",kr:"안데르스는 우리 하이킹 클럽에 가입하기로 했다."}]},
  "andersen": {img:"📖", ex5:[{t:1,en:"Hans Christian Andersen wrote many famous fairy tales.",kr:"한스 크리스티안 안데르센은 많은 유명한 동화를 썼어."},{t:2,en:"I grew up reading stories by Andersen.",kr:"나는 안데르센의 이야기를 읽으며 자랐어."},{t:3,en:"The Little Mermaid is a classic tale by Andersen.",kr:"인어공주는 안데르센의 고전 동화야."},{t:4,en:"We visited the Andersen museum during our trip to Denmark.",kr:"우리는 덴마크 여행 중에 안데르센 박물관을 방문했어."},{t:5,en:"Every child loves the stories written by Andersen.",kr:"모든 아이는 안데르센이 쓴 이야기를 좋아해."}]},
  "anderson": {img:"🏷️", ex5:[{t:1,en:"Mr. Anderson is our history teacher.",kr:"앤더슨 선생님은 우리의 역사 선생님이야."},{t:2,en:"I need to return the book to Ms. Anderson.",kr:"나는 앤더슨 선생님께 그 책을 돌려드려야 해."},{t:3,en:"The Anderson family invited us to dinner.",kr:"앤더슨 가족이 우리를 저녁 식사에 초대했어."},{t:4,en:"Did you see Anderson at the meeting today?",kr:"오늘 회의에서 앤더슨을 봤니?"},{t:5,en:"Anderson is a very common last name.",kr:"앤더슨은 매우 흔한 성이야."}]},
  "andes": {img:"🏔️", ex5:[{t:1,en:"The Andes are a famous mountain range in South America.",kr:"안데스는 남아메리카의 유명한 산맥이다."},{t:2,en:"He dreams of hiking through the Andes someday.",kr:"그는 언젠가 안데스를 하이킹하는 것을 꿈꾼다."},{t:3,en:"The climate changes drastically in the high Andes.",kr:"안데스 고산 지대에서는 기후가 급격하게 변한다."},{t:4,en:"Many ancient civilizations lived in the Andes.",kr:"많은 고대 문명이 안데스 산맥에 살았다."},{t:5,en:"The Andes offer breathtaking views for travelers.",kr:"안데스는 여행자들에게 숨 막히는 경치를 제공한다."}]},
  "andhra": {img:"🗺️", ex5:[{t:1,en:"Andhra Pradesh is a state in southern India.",kr:"안드라프라데시는 인도 남부에 있는 주이다."},{t:2,en:"She is traveling through the Andhra region this summer.",kr:"그녀는 이번 여름에 안드라 지역을 여행하고 있다."},{t:3,en:"The food in Andhra is famous for being very spicy.",kr:"안드라 지역의 음식은 매우 맵기로 유명하다."},{t:4,en:"He is studying the history of the Andhra kingdom.",kr:"그는 안드라 왕국의 역사를 공부하고 있다."},{t:5,en:"Many people in Andhra speak the Telugu language.",kr:"안드라 지역의 많은 사람들은 텔루구어를 사용한다."}]},
  "andi": {img:"👦", ex5:[{t:1,en:"Andi is my best friend from middle school.",kr:"앤디는 내 중학교 단짝 친구이다."},{t:2,en:"I met Andi at the library yesterday morning.",kr:"나는 어제 아침 도서관에서 앤디를 만났다."},{t:3,en:"Can you pass this book to Andi, please?",kr:"이 책을 앤디에게 전해 줄 수 있니?"},{t:4,en:"Andi plays the guitar very well in our school band.",kr:"앤디는 우리 학교 밴드에서 기타를 아주 잘 친다."},{t:5,en:"We are planning a surprise party for Andi's birthday.",kr:"우리는 앤디의 생일을 위한 깜짝 파티를 계획하고 있다."}]},
  "andorra": {img:"🏔️", ex5:[{t:1,en:"Andorra is a small country in the Pyrenees.",kr:"안도라는 피레네산맥에 있는 작은 나라이다."},{t:2,en:"We went skiing in Andorra last winter.",kr:"우리는 지난겨울 안도라로 스키를 타러 갔다."},{t:3,en:"Andorra is known for its beautiful mountain scenery.",kr:"안도라는 아름다운 산악 풍경으로 유명하다."},{t:4,en:"Many tourists visit Andorra for duty-free shopping.",kr:"많은 관광객이 면세 쇼핑을 위해 안도라를 방문한다."},{t:5,en:"He learned about the history of Andorra in school.",kr:"그는 학교에서 안도라의 역사에 대해 배웠다."}]},
