  "asher": {img:"👤", ex5:[{t:1,en:"Asher is playing soccer with his friends.",kr:"애셔는 친구들과 축구를 하고 있다."},{t:2,en:"I met a kind boy named Asher today.",kr:"나는 오늘 애셔라는 이름의 친절한 소년을 만났다."},{t:3,en:"Asher finished his homework early.",kr:"애셔는 숙제를 일찍 끝냈다."},{t:4,en:"Please ask Asher to bring his book.",kr:"애셔에게 책을 가져오라고 말해줘."},{t:5,en:"Asher loves to draw pictures in his notebook.",kr:"애셔는 공책에 그림 그리는 것을 좋아한다."}]},
  "ashes": {img:"⚱️", ex5:[{t:1,en:"Ashes scattered.",kr:"재가 흩어졌다."},{t:2,en:"The ashes are cold.",kr:"그 재는 식었다."},{t:3,en:"We gathered the ashes.",kr:"우리는 재를 모았다."},{t:4,en:"The fire left us ashes.",kr:"그 불은 우리에게 재를 남겼다."},{t:5,en:"We found only ashes remaining.",kr:"우리는 재만 남은 것을 알았다."}]},
  "asheville": {img:"⛰️", ex5:[{t:1,en:"We are visiting Asheville for the weekend.",kr:"우리는 주말 동안 애슈빌을 방문할 예정이다."},{t:2,en:"Asheville is known for its vibrant art scene.",kr:"애슈빌은 활기찬 예술 문화로 유명하다."},{t:3,en:"The mountains around Asheville are breathtaking.",kr:"애슈빌 주변의 산들은 숨이 막힐 정도로 아름답다."},{t:4,en:"Do you like living in Asheville?",kr:"너 애슈빌에 사는 것 좋아하니?"},{t:5,en:"Many tourists enjoy hiking in Asheville.",kr:"많은 관광객들이 애슈빌에서 하이킹하는 것을 즐긴다."}]},
  "ashford": {img:"🏘️", ex5:[{t:1,en:"We are moving to Ashford next month.",kr:"우리는 다음 달에 애슈퍼드로 이사한다."},{t:2,en:"Mr. Ashford is the principal of our school.",kr:"애슈퍼드 선생님은 우리 학교의 교장 선생님이시다."},{t:3,en:"The Ashford library has a great collection of books.",kr:"애슈퍼드 도서관은 훌륭한 책들을 소장하고 있다."},{t:4,en:"I grew up in a small town called Ashford.",kr:"나는 애슈퍼드라는 작은 마을에서 자랐다."},{t:5,en:"The road to Ashford is closed for repairs today.",kr:"애슈퍼드로 가는 길은 오늘 수리 때문에 폐쇄되었다."}]},
  "ashkenazi": {img:"✡️", ex5:[{t:1,en:"My best friend is of Ashkenazi descent.",kr:"내 가장 친한 친구는 아슈케나지 혈통이다."},{t:2,en:"The Ashkenazi Jewish community has a rich history in Eastern Europe.",kr:"아슈케나지 유대인 공동체는 동유럽에 풍부한 역사를 가지고 있다."},{t:3,en:"They follow many traditional Ashkenazi customs.",kr:"그들은 많은 전통적인 아슈케나지 관습을 따른다."},{t:4,en:"Many Ashkenazi families migrated to the United States.",kr:"많은 아슈케나지 가족들이 미국으로 이주했다."},{t:5,en:"The book explores the origins of Ashkenazi culture.",kr:"그 책은 아슈케나지 문화의 기원을 탐구한다."}]},
  "ashland": {img:"📍", ex5:[{t:1,en:"We are planning a road trip to Ashland next week.",kr:"우리는 다음 주에 애슈랜드로 자동차 여행을 갈 계획이다."},{t:2,en:"Ashland is known for its beautiful theater festivals.",kr:"애슈랜드는 아름다운 연극 축제로 유명하다."},{t:3,en:"My cousin lives in a quiet house in Ashland.",kr:"내 사촌은 애슈랜드의 조용한 집에 살고 있다."},{t:4,en:"The autumn leaves in Ashland are absolutely stunning.",kr:"애슈랜드의 가을 단풍은 정말 눈부시게 아름답다."},{t:5,en:"Have you ever visited the town of Ashland?",kr:"애슈랜드라는 마을에 가본 적이 있나요?"}]},
  "ashley": {img:"👩", ex5:[{t:1,en:"Ashley is my best friend from high school.",kr:"애슐리는 내 고등학교 시절 가장 친한 친구입니다."},{t:2,en:"I am going to meet Ashley at the coffee shop today.",kr:"오늘 애슐리를 커피숍에서 만나기로 했습니다."},{t:3,en:"Did you call Ashley to invite her to the party?",kr:"파티에 초대하려고 애슐리에게 전화했나요?"},{t:4,en:"Ashley loves to play the guitar in her free time.",kr:"애슐리는 여가 시간에 기타 연주하는 것을 좋아합니다."},{t:5,en:"I borrowed this book from Ashley last week.",kr:"저는 지난주에 애슐리에게 이 책을 빌렸습니다."}]},
  "ashore": {img:"🏖️", ex5:[{t:1,en:"They swam ashore.",kr:"그들은 헤엄쳐 뭍에 올랐다."},{t:2,en:"The boat is ashore.",kr:"그 배는 뭍에 올라와 있다."},{t:3,en:"We came ashore.",kr:"우리는 뭍에 올랐다."},{t:4,en:"The tide gave us a way ashore.",kr:"조류는 우리에게 뭍으로 갈 길을 주었다."},{t:5,en:"We found debris washed ashore.",kr:"우리는 잔해가 해안에 밀려온 것을 알았다."}]},
  "ashraf": {img:"👤", ex5:[{t:1,en:"Ashraf is my best friend from high school.",kr:"아슈라프는 나의 고등학교 가장 친한 친구야."},{t:2,en:"I sent an email to Ashraf yesterday.",kr:"나는 어제 아슈라프에게 이메일을 보냈어."},{t:3,en:"Ashraf wants to learn how to play the guitar.",kr:"아슈라프는 기타 치는 법을 배우고 싶어 해."},{t:4,en:"Did you see Ashraf at the library today?",kr:"오늘 도서관에서 아슈라프 봤니?"},{t:5,en:"Ashraf is planning to travel to Korea next summer.",kr:"아슈라프는 내년 여름에 한국으로 여행 갈 계획이야."}]},
  "ashram": {img:"🧘", ex5:[{t:1,en:"He decided to spend a month at an ashram in India.",kr:"그는 인도에 있는 아슈람에서 한 달을 보내기로 결심했다."},{t:2,en:"The ashram offers daily meditation and yoga classes.",kr:"그 아슈람은 매일 명상과 요가 수업을 제공한다."},{t:3,en:"Life in the ashram is very simple and peaceful.",kr:"아슈람에서의 삶은 매우 단순하고 평화롭다."},{t:4,en:"Many people visit the ashram to find inner peace.",kr:"많은 사람들이 내면의 평화를 찾기 위해 아슈람을 방문한다."},{t:5,en:"The ashram was founded by a famous spiritual teacher.",kr:"그 아슈람은 유명한 영적 스승에 의해 설립되었다."}]},
  "ashton": {img:"👤", ex5:[{t:1,en:"Ashton is my best friend from school.",kr:"애슈턴은 내 학교 베스트 프렌드야."},{t:2,en:"I saw Ashton playing basketball at the park.",kr:"공원에서 농구하는 애슈턴을 봤어."},{t:3,en:"Did you invite Ashton to the party?",kr:"애슈턴을 파티에 초대했니?"},{t:4,en:"Ashton wants to be a pilot when he grows up.",kr:"애슈턴은 커서 파일럿이 되고 싶어 해."},{t:5,en:"I am waiting for Ashton at the bus stop.",kr:"버스 정류장에서 애슈턴을 기다리는 중이야."}]},
  "ashtray": {img:"🚬", ex5:[{t:1,en:"Please empty the ashtray into the trash bin.",kr:"재떨이를 쓰레기통에 비워 주세요."},{t:2,en:"I found a glass ashtray on the balcony table.",kr:"발코니 탁자 위에서 유리 재떨이를 발견했다."},{t:3,en:"He tapped his cigarette ash into the heavy ashtray.",kr:"그는 담배 재를 무거운 재떨이에 털었다."},{t:4,en:"Smoking is not allowed here, so there is no ashtray.",kr:"여기는 금연 구역이라서 재떨이가 없다."},{t:5,en:"She bought a vintage ashtray for her collection.",kr:"그녀는 수집용으로 빈티지 재떨이를 하나 샀다."}]},
