  "bethel": {img:"⛪", ex5:[{t:1,en:"They visited the historic church in Bethel.",kr:"그들은 베델에 있는 유서 깊은 교회를 방문했습니다."},{t:2,en:"Bethel is a peaceful village in the mountains.",kr:"베델은 산속에 있는 평화로운 마을입니다."},{t:3,en:"We stayed at a cozy inn in Bethel.",kr:"우리는 베델의 아늑한 여관에서 머물렀습니다."},{t:4,en:"Many people go to Bethel for a quiet retreat.",kr:"많은 사람들이 조용한 휴식을 위해 베델로 갑니다."},{t:5,en:"The map shows the road leading to Bethel.",kr:"지도는 베델로 향하는 길을 보여줍니다."}]},
  "bethesda": {img:"📍", ex5:[{t:1,en:"They live in a quiet town called Bethesda.",kr:"그들은 베서스다라는 조용한 마을에 산다."},{t:2,en:"We visited Bethesda for a weekend trip.",kr:"우리는 주말 여행으로 베서스다에 다녀왔다."},{t:3,en:"The hospital in Bethesda is very famous.",kr:"베서스다에 있는 그 병원은 매우 유명하다."},{t:4,en:"He works at a research center in Bethesda.",kr:"그는 베서스다의 한 연구 센터에서 일한다."},{t:5,en:"Many people commute to work from Bethesda.",kr:"많은 사람들이 베서스다에서 출퇴근한다."}]},
  "bethlehem": {img:"✨", ex5:[{t:1,en:"Jesus was born in Bethlehem.",kr:"예수님은 베들레헴에서 태어나셨습니다."},{t:2,en:"Many pilgrims visit Bethlehem every year.",kr:"많은 순례자들이 매년 베들레헴을 방문합니다."},{t:3,en:"The star shone brightly over Bethlehem.",kr:"별이 베들레헴 위에서 밝게 빛났습니다."},{t:4,en:"We are planning a trip to Bethlehem next winter.",kr:"우리는 다음 겨울에 베들레헴으로 여행을 갈 계획입니다."},{t:5,en:"The history of Bethlehem is very long and significant.",kr:"베들레헴의 역사는 매우 길고 중요합니다."}]},
  "betray": {img:"🗡️", ex5:[{t:1,en:"Traitors betray.",kr:"배신자들은 배반한다."},{t:2,en:"His face is betraying fear.",kr:"그의 얼굴이 두려움을 드러내고 있다."},{t:3,en:"We never betray friends.",kr:"우리는 친구를 결코 배신하지 않는다."},{t:4,en:"The leak gave us reason to betray no one.",kr:"그 누설은 우리에게 아무도 배신하지 않을 이유를 주었다."},{t:5,en:"We betray no trust ever.",kr:"우리는 신뢰를 결코 저버리지 않는다."}]},
  "betrayal": {img:"💔", ex5:[{t:1,en:"Betrayal stung.",kr:"배신이 쓰라렸다."},{t:2,en:"The betrayal is deep.",kr:"그 배신은 깊다."},{t:3,en:"We felt the betrayal.",kr:"우리는 그 배신을 느꼈다."},{t:4,en:"The lie gave us a betrayal.",kr:"그 거짓말은 우리에게 배신감을 안겼다."},{t:5,en:"We found the betrayal painful.",kr:"우리는 그 배신이 고통스럽다고 느꼈다."}]},
  "betrayed": {img:"😢", ex5:[{t:1,en:"He felt betrayed.",kr:"그는 배신감을 느꼈다."},{t:2,en:"The trust is betrayed.",kr:"그 신뢰가 배신당했다."},{t:3,en:"They betrayed the cause.",kr:"그들은 그 대의를 저버렸다."},{t:4,en:"The spy betrayed us secrets.",kr:"그 첩자는 우리의 비밀을 팔아넘겼다."},{t:5,en:"We found our trust betrayed.",kr:"우리는 우리의 신뢰가 배신당한 것을 알았다."}]},
  "betraying": {img:"💔", ex5:[{t:1,en:"He felt guilty for betraying his best friend.",kr:"그는 가장 친한 친구를 배신한 것에 대해 죄책감을 느꼈다."},{t:2,en:"She is betraying her principles for money.",kr:"그녀는 돈 때문에 자신의 원칙을 저버리고 있다."},{t:3,en:"His facial expression was betraying his true feelings.",kr:"그의 표정이 그의 진심을 드러내고(배신하고) 있었다."},{t:4,en:"Betraying a secret can ruin a relationship.",kr:"비밀을 누설하는 것은 관계를 망칠 수 있다."},{t:5,en:"They were accused of betraying their country.",kr:"그들은 조국을 배신했다는 혐의를 받았다."}]},
  "betrays": {img:"💔", ex5:[{t:1,en:"He never betrays his friends, no matter what.",kr:"그는 무슨 일이 있어도 친구를 배신하지 않는다."},{t:2,en:"Her tone of voice often betrays her true feelings.",kr:"그녀의 말투는 종종 그녀의 진심을 드러낸다."},{t:3,en:"A true leader never betrays the public trust.",kr:"진정한 지도자는 대중의 신뢰를 저버리지 않는다."},{t:4,en:"The villain betrays his partner in the final scene.",kr:"악당은 마지막 장면에서 자신의 파트너를 배신한다."},{t:5,en:"His shaking hands betrays his nervousness.",kr:"그의 떨리는 손이 그가 긴장했다는 것을 보여준다."}]},
  "betrothed": {img:"💍", ex5:[{t:1,en:"She finally met her betrothed after many years.",kr:"그녀는 수년 만에 드디어 약혼자를 만났다."},{t:2,en:"They are now officially betrothed.",kr:"그들은 이제 공식적으로 약혼한 상태다."},{t:3,en:"He bought a ring for his betrothed.",kr:"그는 약혼자를 위해 반지를 샀다."},{t:4,en:"The couple is happy to be betrothed.",kr:"그 커플은 약혼하게 되어 행복해한다."},{t:5,en:"The king promised his daughter to his betrothed.",kr:"왕은 자신의 딸을 약혼자에게 주기로 약속했다."}]},
