  "birth": {img:"👶", ex5:[{t:1,en:"The birth went well.",kr:"출산이 잘 끝났다."},{t:2,en:"The birth is near.",kr:"출산이 가깝다."},{t:3,en:"We celebrated the birth.",kr:"우리는 그 탄생을 축하했다."},{t:4,en:"The day gave us a birth to cheer.",kr:"그 하루는 우리에게 기뻐할 탄생을 안겼다."},{t:5,en:"We found the birth joyful.",kr:"우리는 그 출산이 기쁘다고 느꼈다."}]},
  "birthday": {img:"🎂", ex5:[{t:1,en:"The birthday came.",kr:"생일이 다가왔다."},{t:2,en:"The birthday is today.",kr:"그 생일은 오늘이다."},{t:3,en:"We threw a birthday party.",kr:"우리는 생일 파티를 열었다."},{t:4,en:"She gave me a birthday gift.",kr:"그녀는 나에게 생일 선물을 주었다."},{t:5,en:"We found the birthday fun.",kr:"우리는 그 생일이 즐겁다고 느꼈다."}]},
  "birthdays": {img:"🎂", ex5:[{t:1,en:"We celebrate our family birthdays with a big dinner.",kr:"우리는 가족 생일을 성대한 저녁 식사로 축하한다."},{t:2,en:"She always remembers all her friends' birthdays.",kr:"그녀는 항상 친구들의 모든 생일을 기억한다."},{t:3,en:"I have three birthdays in my family this month.",kr:"이번 달에 우리 가족 생일이 세 번이나 있다."},{t:4,en:"Children love birthdays because they get many gifts.",kr:"아이들은 선물을 많이 받을 수 있어서 생일을 좋아한다."},{t:5,en:"We usually sing songs on birthdays at school.",kr:"우리는 보통 학교에서 생일 때 노래를 부른다."}]},
  "birthed": {img:"👶", ex5:[{t:1,en:"The lioness birthed three healthy cubs this morning.",kr:"암사자가 오늘 아침 세 마리의 건강한 새끼를 낳았다."},{t:2,en:"She birthed a beautiful baby in the local hospital.",kr:"그녀는 지역 병원에서 예쁜 아기를 낳았다."},{t:3,en:"That era birthed a new movement in modern art.",kr:"그 시대는 현대 미술에서 새로운 운동을 탄생시켰다."},{t:4,en:"The project birthed many innovative ideas for the team.",kr:"그 프로젝트는 팀을 위해 많은 혁신적인 아이디어를 낳았다."},{t:5,en:"The storm birthed a sense of fear among the villagers.",kr:"그 폭풍은 마을 사람들 사이에 두려움을 낳았다."}]},
  "birthing": {img:"👶", ex5:[{t:1,en:"The birthing process can be very exhausting.",kr:"출산 과정은 매우 지칠 수 있습니다."},{t:2,en:"She shared her experience of birthing twins.",kr:"그녀는 쌍둥이를 출산한 자신의 경험을 공유했습니다."},{t:3,en:"Modern hospitals have comfortable rooms for birthing.",kr:"현대식 병원에는 편안한 분만실이 있습니다."},{t:4,en:"The midwife assisted with the birthing at home.",kr:"조산사가 집에서 이루어진 출산을 도왔습니다."},{t:5,en:"They are preparing for the birthing of the new calf.",kr:"그들은 새끼 송아지의 탄생을 준비하고 있습니다."}]},
  "birthplace": {img:"🏠", ex5:[{t:1,en:"Seoul is the birthplace of many famous people.",kr:"서울은 많은 유명 인사의 출생지야."},{t:2,en:"We visited the birthplace of the great poet.",kr:"우리는 그 위대한 시인의 생가를 방문했어."},{t:3,en:"This city is known as the birthplace of jazz.",kr:"이 도시는 재즈의 발상지로 알려져 있어."},{t:4,en:"He returned to his birthplace after many years.",kr:"그는 여러 해 만에 자신의 출생지로 돌아왔어."},{t:5,en:"Is this small village the birthplace of your father?",kr:"이 작은 마을이 너희 아버지의 고향이니?"}]},
  "birthright": {img:"👑", ex5:[{t:1,en:"Freedom is every human's birthright.",kr:"자유는 모든 인간의 생득권이야."},{t:2,en:"He claimed the land as his birthright.",kr:"그는 그 땅이 자신의 타고난 권리라고 주장했어."},{t:3,en:"Education is a birthright for every child.",kr:"교육은 모든 아이의 타고난 권리야."},{t:4,en:"She never forgot her birthright as a princess.",kr:"그녀는 공주로서의 자신의 타고난 권리를 잊지 않았어."},{t:5,en:"They fought to protect their birthright.",kr:"그들은 그들의 타고난 권리를 지키기 위해 싸웠어."}]},
  "births": {img:"👶", ex5:[{t:1,en:"The hospital records many births every day.",kr:"그 병원에서는 매일 많은 출생이 기록된다."},{t:2,en:"We celebrated the births of our twin kittens.",kr:"우리는 쌍둥이 아기 고양이들의 탄생을 축하했다."},{t:3,en:"The rate of births has changed this year.",kr:"올해 출생률이 변했다."},{t:4,en:"He studies the history of human births.",kr:"그는 인간 탄생의 역사를 연구한다."},{t:5,en:"The news reported a record number of births.",kr:"뉴스는 기록적인 출생아 수를 보도했다."}]},
