  "kang": {img:"🇰🇷", ex5:[{t:1,en:"Kang is a very common family name in Korea.",kr:"강 씨는 한국에서 매우 흔한 성씨이다."},{t:2,en:"I have a friend named Kang who plays soccer well.",kr:"나에게는 축구를 잘하는 강이라는 친구가 있다."},{t:3,en:"Professor Kang will give a lecture tomorrow.",kr:"강 교수님께서 내일 강의를 하실 것이다."},{t:4,en:"I sent an email to Kang to ask for the files.",kr:"나는 파일을 요청하기 위해 강에게 이메일을 보냈다."},{t:5,en:"The book was written by an author named Kang.",kr:"그 책은 강이라는 작가에 의해 쓰였다."}]},
  "kangaroo": {img:"🦘", ex5:[{t:1,en:"The kangaroo hopped across the field.",kr:"그 캥거루가 들판을 가로질러 뛰었다."},{t:2,en:"A kangaroo carries its young in a pouch.",kr:"캥거루는 주머니에 새끼를 넣어 다닌다."},{t:3,en:"The kangaroo has strong back legs.",kr:"그 캥거루는 튼튼한 뒷다리를 가졌다."},{t:4,en:"A young kangaroo peeked from the pouch.",kr:"어린 캥거루가 주머니에서 빼꼼히 내다봤다."},{t:5,en:"The kangaroo grazed in the morning.",kr:"그 캥거루가 아침에 풀을 뜯었다."}]},
  "kangaroos": {img:"🦘", ex5:[{t:1,en:"We saw many kangaroos jumping in the outback.",kr:"우리는 오지에서 껑충껑충 뛰는 많은 캥거루를 보았다."},{t:2,en:"Kangaroos are famous for carrying their babies in pouches.",kr:"캥거루는 주머니에 새끼를 넣고 다니는 것으로 유명하다."},{t:3,en:"The zoo has a special area for visitors to feed kangaroos.",kr:"그 동물원에는 관람객이 캥거루에게 먹이를 줄 수 있는 특별한 구역이 있다."},{t:4,en:"Kangaroos can travel very fast across the grass.",kr:"캥거루는 풀밭을 아주 빠르게 가로질러 이동할 수 있다."},{t:5,en:"I took a photo of the kangaroos during my trip to Australia.",kr:"나는 호주 여행 중에 캥거루 사진을 찍었다."}]},
  "kanji": {img:"✍️", ex5:[{t:1,en:"Learning kanji is the hardest part of studying Japanese.",kr:"한자를 배우는 것은 일본어 공부에서 가장 어려운 부분입니다."},{t:2,en:"He can write his name in kanji characters.",kr:"그는 자신의 이름을 한자로 쓸 수 있습니다."},{t:3,en:"This dictionary helps you find kanji easily.",kr:"이 사전은 한자를 쉽게 찾을 수 있도록 도와줍니다."},{t:4,en:"How many kanji do we need to memorize for the test?",kr:"시험을 위해 우리는 한자를 몇 개나 외워야 하나요?"},{t:5,en:"She practiced writing kanji on a grid notebook.",kr:"그녀는 모눈종이 공책에 한자 쓰는 연습을 했다."}]},
  "kannada": {img:"🇮🇳", ex5:[{t:1,en:"Kannada is a beautiful language spoken in southern India.",kr:"칸나다어는 인도 남부에서 사용되는 아름다운 언어입니다."},{t:2,en:"She is learning to read and write in Kannada.",kr:"그녀는 칸나다어를 읽고 쓰는 법을 배우고 있습니다."},{t:3,en:"The movie features dialogue in the Kannada language.",kr:"그 영화는 칸나다어 대사가 나옵니다."},{t:4,en:"Many people in Karnataka communicate using Kannada.",kr:"카르나타카주의 많은 사람들이 칸나다어로 의사소통합니다."},{t:5,en:"I found a book written in Kannada at the library.",kr:"도서관에서 칸나다어로 쓰인 책을 찾았습니다."}]},
  "kano": {img:"🌍", ex5:[{t:1,en:"Kano is a large city in northern Nigeria.",kr:"카노는 나이지리아 북부에 있는 큰 도시이다."},{t:2,en:"We learned about the history of Kano in class.",kr:"우리는 수업 시간에 카노의 역사에 대해 배웠다."},{t:3,en:"Kano is an important center for trade and culture.",kr:"카노는 무역과 문화의 중요한 중심지이다."},{t:4,en:"My colleague traveled to Kano for business last week.",kr:"내 동료는 지난주에 업무차 카노로 출장을 갔다."},{t:5,en:"The markets in Kano are very busy and colorful.",kr:"카노의 시장은 매우 붐비고 다채롭다."}]},
